/// <summary>A faction: its table Id (Savage, Filth, Classic), the name the game shows, and its icon.</summary>
internal sealed record AuguryFaction(string Id, string Name, string Icon);

/// <summary>
/// One Fate: its table Id, the name the game shows, its faction's Id, its card art, and its three tiers.
/// </summary>
internal sealed record AuguryFate(string Id, string Name, string FactionId, string Art, AuguryFateTier[] Tiers);

/// <summary>
/// One tier of a Fate: the card's short text, the full text in the game's markup, and the monster mod the
/// boss gets, with its stats and values ("stat_id min - max").
/// </summary>
internal sealed record AuguryFateTier(int Tier, string Description, string Body, string ModKey, string[] ModStats);

/// <summary>
/// One reward outcome: its table Id; its family (the Id without the HardMode prefix or level-band digit, so
/// one family is one reward across area levels; the digit kept where two rows read differently at the same
/// levels and tier, as the two Divine Orb rewards do); its tier; whether it is of the HardMode set; the text
/// the panel shows; the area levels it can roll at; its icon; the monster mods that make its drops; and the
/// challenge it counts towards.
/// </summary>
internal sealed record AuguryReward(string Id, string Family, int Tier, bool HardMode, string Description,
    int MinLevel, int MaxLevel, string Icon, string[] DropMods, string Achievement);
